response:
 You can use the Canvas component to draw shapes on the screen using Three.js. It’s pretty easy to do, here’s a simple example:

import * as THREE from "three";
import { Canvas } from "@react-three/fiber";

const App = () => {
  const [shape, setShape] = useState("");

  const onChange = (event) => {
    setShape(event.target.value);
  };

  const render = () => {
    const geometry = new THREE.BoxGeometry(40, 40, 40);
    const material = new THREE.MeshBasicMaterial({color: "red"});
    const mesh = new THREE.Mesh(geometry, material);
    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(0, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();

    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.setClearColor(0xcccccc);
    renderer.setSize(window.innerWidth, window.innerHeight);

    scene.add(mesh);
    renderer.render(scene, camera);

    document.getElementById("app").appendChild(renderer.domElement);
  };

  return (
    <>
      <input type="text" value={shape} onChange={onChange} />
      <button onClick={render}>Render</button>
    </>
  );
};

export default App;

